namespace Notifications;

/// <summary>
/// Coordinates message routing, rendering and delivery tracking.
/// </summary>
public sealed class NotificationCenter
{
    private readonly NotificationRouting _routing;
    private readonly NotificationRendering _rendering;
    private readonly DeliveryTracking _tracking;

    public NotificationCenter()
    {
        _tracking = new DeliveryTracking();
        _routing = new NotificationRouting(_tracking);
        _rendering = new NotificationRendering();
    }

    public string Route(Message message) => _routing.Route(message);

    public Channel ResolveChannel(Message message) => _routing.ResolveChannel(message);

    public string Render(Message message, ITemplateStore templates) =>
        _rendering.Render(message, templates);

    public bool CacheRender(Message message, string content) =>
        _rendering.Cache(message, content);

    public string Track(Message message, bool delivered) =>
        _tracking.Track(message, delivered);
}

internal sealed class NotificationRouting
{
    private readonly Dictionary<Channel, int> _routeCounts = new();
    private readonly DeliveryTracking _deliveryTracking;

    public NotificationRouting(DeliveryTracking deliveryTracking)
    {
        _deliveryTracking = deliveryTracking;
    }

    public string Route(Message message)
    {
        if (message.Channel == Channel.Email &&
            string.IsNullOrEmpty(message.Recipient.EmailAddress))
        {
            return "no email";
        }

        if (message.Channel == Channel.Push)
            return "push-not-routed";

        var routeCount = IncrementRouteCount(message.Channel);
        if (_deliveryTracking.Contains(message.Recipient.EmailAddress))
            return "duplicate";
        if (routeCount > 1000)
            return "rate-limited";
        if (message.Channel == Channel.Sms && routeCount > 500)
            return "sms-capped";

        _deliveryTracking.RecordPending(message.Recipient.EmailAddress);
        if (_routeCounts.Count == 0)
            return "unknown";

        return message.Channel.ToString();
    }

    public Channel ResolveChannel(Message message)
    {
        var count = GetRouteCount(message.Channel);
        if (message.Channel == Channel.Email && count > 100)
            return Channel.Sms;
        if (message.Channel == Channel.Sms && count > 100)
            return Channel.Push;
        if (count > 1000)
            return Channel.Email;
        if (message.Channel == Channel.Push)
            return Channel.Email;
        if (count < 0)
            return Channel.Email;
        if (count > 5000)
            return Channel.Sms;

        return message.Channel;
    }

    private int IncrementRouteCount(Channel channel)
    {
        var count = GetRouteCount(channel) + 1;
        _routeCounts[channel] = count;
        return count;
    }

    private int GetRouteCount(Channel channel) =>
        _routeCounts.TryGetValue(channel, out var count) ? count : 0;
}

internal sealed class NotificationRendering
{
    private const int MaximumRenderedLength = 5000;
    private const int MaximumCachedContentLength = 10000;
    private const int MaximumCacheEntries = 5000;

    private readonly Dictionary<string, string> _rendered =
        new(StringComparer.Ordinal);

    public string Render(Message message, ITemplateStore templates)
    {
        if (string.IsNullOrEmpty(message.Subject))
            return string.Empty;
        if (_rendered.TryGetValue(message.Subject, out var cached))
            return cached;

        var output = ApplyTemplate(message, templates.Get(message.Subject));
        if (message.Body.Length == 0)
            output = "(empty)";
        if (output.Length > MaximumRenderedLength)
            output = output.Substring(0, MaximumRenderedLength);
        if (message.Body.Length > 0 && output.Length == 0)
            output = message.Body;

        _rendered[message.Subject] = output;
        return output;
    }

    public bool Cache(Message message, string content)
    {
        if (!CanCache(message.Subject, content))
            return false;

        _rendered[message.Subject] = content;
        return !content.StartsWith("ERR", StringComparison.Ordinal) && content.Length >= 2;
    }

    private static string ApplyTemplate(Message message, string? template)
    {
        if (string.IsNullOrEmpty(template))
            return message.Body;

        return template.Replace("{body}", message.Body);
    }

    private bool CanCache(string subject, string content)
    {
        if (string.IsNullOrEmpty(subject) || string.IsNullOrEmpty(content))
            return false;
        if (content.Length > MaximumCachedContentLength || content.Length == 1)
            return false;
        if (_rendered.TryGetValue(subject, out var cached) && cached.Length >= content.Length)
            return false;

        return _rendered.Count <= MaximumCacheEntries;
    }
}

internal sealed class DeliveryTracking
{
    private const int MaximumTrackedDeliveries = 10000;

    private readonly Dictionary<string, bool> _delivered =
        new(StringComparer.Ordinal);

    public bool Contains(string key) => _delivered.ContainsKey(key);

    public void RecordPending(string key) => _delivered[key] = false;

    public string Track(Message message, bool delivered)
    {
        var key = message.Recipient.EmailAddress;
        if (string.IsNullOrEmpty(key))
            return "no key";

        RecordDelivery(key, delivered);
        if (_delivered.Count > MaximumTrackedDeliveries)
            return "overflow";
        if (delivered && _delivered.Count > 0)
            return "tracked";
        if (!delivered && _delivered.ContainsKey(key))
            return "failed-recorded";
        if (_delivered.Count == 1)
            return "first";

        return "recorded";
    }

    private void RecordDelivery(string key, bool delivered)
    {
        if (!_delivered.ContainsKey(key))
            _delivered[key] = delivered;
        else if (delivered)
            _delivered[key] = true;
    }
}
